// Extraer datos del mensaje de Whapi
const msg = $input.first().json.body.messages[0];
const sender = msg.from;           // ej: '573001234567@s.whatsapp.net'
const phone = sender.split('@')[0]; // '573001234567'
const text = msg.text?.body || msg.caption || '[media]';
const messageId = msg.id;

// Historial: n8n guarda conversaciones en workflow static data
const workflowData = $getWorkflowStaticData('global');
if (!workflowData.conversations) workflowData.conversations = {};

const history = workflowData.conversations[phone] || [];

// Agregar mensaje del usuario al historial
history.push({ role: 'user', content: text });

// Limitar historial a últimos 20 turnos (10 de cada lado)
if (history.length > 20) history.splice(0, history.length - 20);

workflowData.conversations[phone] = history;

return [{ json: { phone, text, history, sender, messageId } }];

// Guardar respuesta del asistente en el historial
const claudeResponse = $input.first().json;
const assistantText = claudeResponse.content[0].text;

// Recuperar datos del mensaje original
const phone = $('Extraer mensaje e historial').first().json.phone;

const workflowData = $getWorkflowStaticData('global');
const history = workflowData.conversations[phone] || [];
history.push({ role: 'assistant', content: assistantText });
workflowData.conversations[phone] = history;

// Detectar si es lead calificado
const isLead = assistantText.includes('[LEAD:');
const leadMatch = assistantText.match(/\[LEAD: (.+?)\]/);
const leadData = leadMatch ? leadMatch[1] : null;

// Limpiar texto (quitar el tag de lead antes de enviar)
const cleanText = assistantText.replace(/\[LEAD:.*?\]/g, '').trim();

return [{ json: { 
  phone, 
  responseText: cleanText, 
  isLead, 
  leadData,
  sender: $('Extraer mensaje e historial').first().json.sender
} }];

